    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    TRY_CAST(NULLIF(trim(`fiscal_year`), '') AS INT) AS `fiscal_year`,
    CASE WHEN lower(trim(`is_baseline_calendar`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_baseline_calendar`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_baseline_calendar`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    COALESCE(try_to_date(trim(`locked_date`), 'yyyy-MM-dd'), try_to_date(trim(`locked_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`locked_date`) AS DATE)) AS `locked_date`,
    NULLIF(trim(`notes`), '') AS `notes`,
    TRY_CAST(NULLIF(trim(`planned_event_count`), '') AS INT) AS `planned_event_count`,
    CASE lower(trim(`planning_cycle`))
      WHEN 'annual' THEN 'annual'
      WHEN 'semi-annual' THEN 'semi-annual'
      WHEN 'quarterly' THEN 'quarterly'
      WHEN 'monthly' THEN 'monthly'
      ELSE NULLIF(trim(`planning_cycle`), '')
    END AS `planning_cycle`,
    CASE lower(trim(`pricing_strategy`))
      WHEN 'hi-lo' THEN 'hi-lo'
      WHEN 'edlp' THEN 'edlp'
      WHEN 'hybrid' THEN 'hybrid'
      WHEN 'promotional' THEN 'promotional'
      WHEN 'premium' THEN 'premium'
      ELSE NULLIF(trim(`pricing_strategy`), '')
    END AS `pricing_strategy`,
    NULLIF(trim(`region_code`), '') AS `region_code`,
    TRY_CAST(NULLIF(trim(`total_planned_trade_spend`), '') AS DECIMAL(18,2)) AS `total_planned_trade_spend`,
    NULLIF(trim(`tpm_system_code`), '') AS `tpm_system_code`,
    TRY_CAST(NULLIF(trim(`version_number`), '') AS INT) AS `version_number`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.promotion_trade_calendar
)
SELECT *
FROM typed
QUALIFY `trade_calendar_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `trade_calendar_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- promotion.trade_spend_allocation ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.promotion_trade_spend_allocation (
