)
COMMENT 'Silver: promotion.trade_spend_allocation typed and cleaned, one row per trade_spend_allocation_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`trade_spend_allocation_id`), '') AS BIGINT) AS `trade_spend_allocation_id`,
    TRY_CAST(NULLIF(trim(`demand_plan_id`), '') AS BIGINT) AS `demand_plan_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`funding_agreement_id`), '') AS BIGINT) AS `funding_agreement_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    TRY_CAST(NULLIF(trim(`trade_calendar_id`), '') AS BIGINT) AS `trade_calendar_id`,
    TRY_CAST(NULLIF(trim(`trade_promotion_id`), '') AS BIGINT) AS `trade_promotion_id`,
    TRY_CAST(NULLIF(trim(`accrual_amount`), '') AS DECIMAL(18,2)) AS `accrual_amount`,
    TRY_CAST(NULLIF(trim(`actual_amount`), '') AS DECIMAL(18,2)) AS `actual_amount`,
    TRY_CAST(NULLIF(trim(`actual_volume`), '') AS DECIMAL(15,3)) AS `actual_volume`,
    TRY_CAST(NULLIF(trim(`allocated_amount`), '') AS DECIMAL(18,2)) AS `allocated_amount`,
    COALESCE(try_to_date(trim(`allocation_date`), 'yyyy-MM-dd'), try_to_date(trim(`allocation_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`allocation_date`) AS DATE)) AS `allocation_date`,
    NULLIF(trim(`allocation_number`), '') AS `allocation_number`,
    NULLIF(trim(`allocation_status`), '') AS `allocation_status`,
    COALESCE(try_to_date(trim(`approval_date`), 'yyyy-MM-dd'), try_to_date(trim(`approval_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approval_date`) AS DATE)) AS `approval_date`,
    TRY_CAST(NULLIF(trim(`baseline_volume`), '') AS DECIMAL(15,3)) AS `baseline_volume`,
    TRY_CAST(NULLIF(trim(`committed_amount`), '') AS DECIMAL(18,2)) AS `committed_amount`,
    NULLIF(trim(`cost_center_code`), '') AS `cost_center_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`deduction_amount`), '') AS DECIMAL(18,2)) AS `deduction_amount`,
    TRY_CAST(NULLIF(trim(`fiscal_period`), '') AS INT) AS `fiscal_period`,
    TRY_CAST(NULLIF(trim(`fiscal_year`), '') AS INT) AS `fiscal_year`,
    TRY_CAST(NULLIF(trim(`gmroi_percentage`), '') AS DECIMAL(5,2)) AS `gmroi_percentage`,
    CASE WHEN lower(trim(`is_active`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_active`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_active`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    NULLIF(trim(`notes`), '') AS `notes`,
    CASE lower(trim(`pricing_strategy`))
      WHEN 'hi_lo' THEN 'hi_lo'
      WHEN 'edlp' THEN 'edlp'
      WHEN 'hybrid' THEN 'hybrid'
      WHEN 'premium' THEN 'premium'
      WHEN 'penetration' THEN 'penetration'
      WHEN 'competitive' THEN 'competitive'
      ELSE NULLIF(trim(`pricing_strategy`), '')
    END AS `pricing_strategy`,
    NULLIF(trim(`profit_center_code`), '') AS `profit_center_code`,
    COALESCE(try_to_date(trim(`promotion_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`promotion_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`promotion_end_date`) AS DATE)) AS `promotion_end_date`,
    COALESCE(try_to_date(trim(`promotion_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`promotion_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`promotion_start_date`) AS DATE)) AS `promotion_start_date`,
    TRY_CAST(NULLIF(trim(`roi_percentage`), '') AS DECIMAL(5,2)) AS `roi_percentage`,
    TRY_CAST(NULLIF(trim(`settlement_amount`), '') AS DECIMAL(18,2)) AS `settlement_amount`,
    COALESCE(try_to_date(trim(`settlement_date`), 'yyyy-MM-dd'), try_to_date(trim(`settlement_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`settlement_date`) AS DATE)) AS `settlement_date`,
    CASE lower(trim(`spend_category`))
      WHEN 'price_discount' THEN 'price_discount'
      WHEN 'merchandising' THEN 'merchandising'
      WHEN 'marketing' THEN 'marketing'
      WHEN 'listing' THEN 'listing'
      WHEN 'performance_incentive' THEN 'performance_incentive'
      WHEN 'other' THEN 'other'
      ELSE NULLIF(trim(`spend_category`), '')
    END AS `spend_category`,
    CASE lower(trim(`spend_type`))
      WHEN 'off_invoice_discount' THEN 'off_invoice_discount'
      WHEN 'scan_back' THEN 'scan_back'
      WHEN 'bill_back' THEN 'bill_back'
      WHEN 'lump_sum' THEN 'lump_sum'
      WHEN 'coop_advertising' THEN 'coop_advertising'
      WHEN 'slotting_fee' THEN 'slotting_fee'
      ELSE NULLIF(trim(`spend_type`), '')
    END AS `spend_type`,
    TRY_CAST(NULLIF(trim(`target_volume`), '') AS DECIMAL(15,3)) AS `target_volume`,
    TRY_CAST(NULLIF(trim(`variance_amount`), '') AS DECIMAL(18,2)) AS `variance_amount`,
    CASE lower(trim(`volume_uom`))
      WHEN 'units' THEN 'units'
      WHEN 'cases' THEN 'cases'
      WHEN 'pallets' THEN 'pallets'
      WHEN 'kg' THEN 'kg'
      WHEN 'liters' THEN 'liters'
      ELSE NULLIF(trim(`volume_uom`), '')
    END AS `volume_uom`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.promotion_trade_spend_allocation
)
SELECT *
FROM typed
QUALIFY `trade_spend_allocation_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `trade_spend_allocation_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- promotion.funding_agreement ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.promotion_funding_agreement (
