)
COMMENT 'Silver: promotion.funding_agreement typed and cleaned, one row per funding_agreement_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`funding_agreement_id`), '') AS BIGINT) AS `funding_agreement_id`,
    TRY_CAST(NULLIF(trim(`brand_id`), '') AS BIGINT) AS `brand_id`,
