    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    CASE lower(trim(`accrual_method`))
      WHEN 'straight_line' THEN 'straight_line'
      WHEN 'event_based' THEN 'event_based'
      WHEN 'scan_based' THEN 'scan_based'
      WHEN 'milestone_based' THEN 'milestone_based'
