    END AS `accrual_method`,
    TRY_CAST(NULLIF(trim(`accrued_to_date_amount`), '') AS DECIMAL(18,2)) AS `accrued_to_date_amount`,
    NULLIF(trim(`agreement_name`), '') AS `agreement_name`,
    NULLIF(trim(`agreement_number`), '') AS `agreement_number`,
    NULLIF(trim(`agreement_status`), '') AS `agreement_status`,
    CASE lower(trim(`agreement_type`))
      WHEN 'annual_lump_sum' THEN 'annual_lump_sum'
      WHEN 'scan_back' THEN 'scan_back'
      WHEN 'co_op' THEN 'co_op'
      WHEN 'slotting' THEN 'slotting'
      WHEN 'performance_based' THEN 'performance_based'
      WHEN 'volume_rebate' THEN 'volume_rebate'
      ELSE NULLIF(trim(`agreement_type`), '')
    END AS `agreement_type`,
    CASE lower(trim(`approval_status`))
      WHEN 'not_submitted' THEN 'not_submitted'
      WHEN 'pending_review' THEN 'pending_review'
      WHEN 'approved' THEN 'approved'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'revision_required' THEN 'revision_required'
      ELSE NULLIF(trim(`approval_status`), '')
    END AS `approval_status`,
    NULLIF(trim(`approved_by`), '') AS `approved_by`,
    COALESCE(try_to_date(trim(`approved_date`), 'yyyy-MM-dd'), try_to_date(trim(`approved_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approved_date`) AS DATE)) AS `approved_date`,
    CASE WHEN lower(trim(`auto_renewal_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`auto_renewal_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `auto_renewal_flag`,
    NULLIF(trim(`contract_document_url`), '') AS `contract_document_url`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    NULLIF(trim(`deduction_settlement_terms`), '') AS `deduction_settlement_terms`,
    COALESCE(try_to_date(trim(`funding_period_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`funding_period_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`funding_period_end_date`) AS DATE)) AS `funding_period_end_date`,
    COALESCE(try_to_date(trim(`funding_period_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`funding_period_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`funding_period_start_date`) AS DATE)) AS `funding_period_start_date`,
    TRY_CAST(NULLIF(trim(`gmroi_target`), '') AS DECIMAL(5,2)) AS `gmroi_target`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    NULLIF(trim(`manufacturer_signatory_name`), '') AS `manufacturer_signatory_name`,
    NULLIF(trim(`manufacturer_signatory_title`), '') AS `manufacturer_signatory_title`,
    COALESCE(try_to_date(trim(`manufacturer_signature_date`), 'yyyy-MM-dd'), try_to_date(trim(`manufacturer_signature_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`manufacturer_signature_date`) AS DATE)) AS `manufacturer_signature_date`,
    NULLIF(trim(`notes`), '') AS `notes`,
    TRY_CAST(NULLIF(trim(`paid_to_date_amount`), '') AS DECIMAL(18,2)) AS `paid_to_date_amount`,
    CASE lower(trim(`payment_frequency`))
      WHEN 'one_time' THEN 'one_time'
      WHEN 'monthly' THEN 'monthly'
      WHEN 'quarterly' THEN 'quarterly'
      WHEN 'semi_annual' THEN 'semi_annual'
      WHEN 'annual' THEN 'annual'
      WHEN 'event_based' THEN 'event_based'
      ELSE NULLIF(trim(`payment_frequency`), '')
    END AS `payment_frequency`,
    NULLIF(trim(`payment_terms`), '') AS `payment_terms`,
    NULLIF(trim(`performance_conditions`), '') AS `performance_conditions`,
    TRY_CAST(NULLIF(trim(`remaining_balance_amount`), '') AS DECIMAL(18,2)) AS `remaining_balance_amount`,
    CASE WHEN lower(trim(`renewal_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`renewal_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `renewal_flag`,
    NULLIF(trim(`retailer_signatory_name`), '') AS `retailer_signatory_name`,
    NULLIF(trim(`retailer_signatory_title`), '') AS `retailer_signatory_title`,
    COALESCE(try_to_date(trim(`retailer_signature_date`), 'yyyy-MM-dd'), try_to_date(trim(`retailer_signature_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`retailer_signature_date`) AS DATE)) AS `retailer_signature_date`,
    TRY_CAST(NULLIF(trim(`roi_target_percentage`), '') AS DECIMAL(5,2)) AS `roi_target_percentage`,
    COALESCE(try_to_date(trim(`termination_date`), 'yyyy-MM-dd'), try_to_date(trim(`termination_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`termination_date`) AS DATE)) AS `termination_date`,
    TRY_CAST(NULLIF(trim(`termination_notice_days`), '') AS INT) AS `termination_notice_days`,
    NULLIF(trim(`termination_reason`), '') AS `termination_reason`,
    TRY_CAST(NULLIF(trim(`total_committed_amount`), '') AS DECIMAL(18,2)) AS `total_committed_amount`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.promotion_funding_agreement
)
SELECT *
FROM typed
QUALIFY `funding_agreement_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `funding_agreement_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- promotion.accrual ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.promotion_accrual (
  CONSTRAINT `accrual_id_not_null` EXPECT (`accrual_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: promotion.accrual typed and cleaned, one row per accrual_id (latest modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`accrual_id`), '') AS BIGINT) AS `accrual_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`funding_agreement_id`), '') AS BIGINT) AS `funding_agreement_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    TRY_CAST(NULLIF(trim(`trade_promotion_id`), '') AS BIGINT) AS `trade_promotion_id`,
    NULLIF(trim(`accrual_number`), '') AS `accrual_number`,
    CASE lower(trim(`accrual_status`))
      WHEN 'open' THEN 'open'
      WHEN 'pending_approval' THEN 'pending_approval'
      WHEN 'approved' THEN 'approved'
      WHEN 'settled' THEN 'settled'
      WHEN 'reversed' THEN 'reversed'
      WHEN 'cancelled' THEN 'cancelled'
      ELSE NULLIF(trim(`accrual_status`), '')
    END AS `accrual_status`,
    CASE lower(trim(`accrual_type`))
      WHEN 'scan_back' THEN 'scan_back'
      WHEN 'bill_back' THEN 'bill_back'
      WHEN 'off_invoice' THEN 'off_invoice'
      WHEN 'lump_sum' THEN 'lump_sum'
      WHEN 'volume_rebate' THEN 'volume_rebate'
      WHEN 'performance_bonus' THEN 'performance_bonus'
      ELSE NULLIF(trim(`accrual_type`), '')
    END AS `accrual_type`,
    TRY_CAST(NULLIF(trim(`amount`), '') AS DECIMAL(18,2)) AS `amount`,
    CASE lower(trim(`approval_status`))
      WHEN 'pending' THEN 'pending'
      WHEN 'approved' THEN 'approved'
      WHEN 'rejected' THEN 'rejected'
      ELSE NULLIF(trim(`approval_status`), '')
    END AS `approval_status`,
    COALESCE(try_to_timestamp(trim(`approval_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approval_timestamp`) AS TIMESTAMP)) AS `approval_timestamp`,
    TRY_CAST(NULLIF(trim(`baseline_volume`), '') AS DECIMAL(18,3)) AS `baseline_volume`,
    NULLIF(trim(`cost_center_code`), '') AS `cost_center_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    NULLIF(trim(`deduction_claim_number`), '') AS `deduction_claim_number`,
    NULLIF(trim(`dispute_reason`), '') AS `dispute_reason`,
    TRY_CAST(NULLIF(trim(`fiscal_period`), '') AS INT) AS `fiscal_period`,
    TRY_CAST(NULLIF(trim(`fiscal_year`), '') AS INT) AS `fiscal_year`,
    TRY_CAST(NULLIF(trim(`gmroi`), '') AS DECIMAL(10,2)) AS `gmroi`,
    TRY_CAST(NULLIF(trim(`incremental_volume`), '') AS DECIMAL(18,3)) AS `incremental_volume`,
    CASE WHEN lower(trim(`is_disputed`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_disputed`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_disputed`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    NULLIF(trim(`notes`), '') AS `notes`,
    NULLIF(trim(`payment_reference_number`), '') AS `payment_reference_number`,
    COALESCE(try_to_date(trim(`period_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`period_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`period_end_date`) AS DATE)) AS `period_end_date`,
    COALESCE(try_to_date(trim(`period_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`period_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`period_start_date`) AS DATE)) AS `period_start_date`,
    NULLIF(trim(`profit_center_code`), '') AS `profit_center_code`,
    TRY_CAST(NULLIF(trim(`quantity_sold`), '') AS DECIMAL(18,3)) AS `quantity_sold`,
    TRY_CAST(NULLIF(trim(`rate`), '') AS DECIMAL(10,4)) AS `rate`,
    COALESCE(try_to_date(trim(`recognition_date`), 'yyyy-MM-dd'), try_to_date(trim(`recognition_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`recognition_date`) AS DATE)) AS `recognition_date`,
    COALESCE(try_to_date(trim(`reversal_date`), 'yyyy-MM-dd'), try_to_date(trim(`reversal_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`reversal_date`) AS DATE)) AS `reversal_date`,
    TRY_CAST(NULLIF(trim(`roi_percentage`), '') AS DECIMAL(10,2)) AS `roi_percentage`,
    NULLIF(trim(`sap_co_document_number`), '') AS `sap_co_document_number`,
    NULLIF(trim(`sap_fi_document_number`), '') AS `sap_fi_document_number`,
    COALESCE(try_to_date(trim(`settlement_date`), 'yyyy-MM-dd'), try_to_date(trim(`settlement_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`settlement_date`) AS DATE)) AS `settlement_date`,
    NULLIF(trim(`source_system_code`), '') AS `source_system_code`,
    CASE lower(trim(`unit_of_measure`))
      WHEN 'each' THEN 'each'
      WHEN 'case' THEN 'case'
      WHEN 'pallet' THEN 'pallet'
      WHEN 'kilogram' THEN 'kilogram'
      WHEN 'liter' THEN 'liter'
      ELSE NULLIF(trim(`unit_of_measure`), '')
    END AS `unit_of_measure`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.promotion_accrual
)
SELECT *
FROM typed
QUALIFY `accrual_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `accrual_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

