    TRY_CAST(NULLIF(trim(`aging_days`), '') AS INT) AS `aging_days`,
    TRY_CAST(NULLIF(trim(`amount`), '') AS DECIMAL(18,2)) AS `amount`,
    COALESCE(try_to_date(trim(`approval_date`), 'yyyy-MM-dd'), try_to_date(trim(`approval_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approval_date`) AS DATE)) AS `approval_date`,
    TRY_CAST(NULLIF(trim(`approved_amount`), '') AS DECIMAL(18,2)) AS `approved_amount`,
    NULLIF(trim(`business_unit_code`), '') AS `business_unit_code`,
    NULLIF(trim(`claim_reference_number`), '') AS `claim_reference_number`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    COALESCE(try_to_date(trim(`deduction_date`), 'yyyy-MM-dd'), try_to_date(trim(`deduction_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`deduction_date`) AS DATE)) AS `deduction_date`,
    NULLIF(trim(`deduction_number`), '') AS `deduction_number`,
    NULLIF(trim(`deduction_type`), '') AS `deduction_type`,
    NULLIF(trim(`dispute_reason`), '') AS `dispute_reason`,
    CASE lower(trim(`dispute_status`))
      WHEN 'open' THEN 'open'
      WHEN 'approved' THEN 'approved'
      WHEN 'disputed' THEN 'disputed'
      WHEN 'partially_approved' THEN 'partially_approved'
      WHEN 'written_off' THEN 'written_off'
      WHEN 'pending_review' THEN 'pending_review'
      ELSE NULLIF(trim(`dispute_status`), '')
    END AS `dispute_status`,
    TRY_CAST(NULLIF(trim(`disputed_amount`), '') AS DECIMAL(18,2)) AS `disputed_amount`,
    TRY_CAST(NULLIF(trim(`gmroi_impact_percentage`), '') AS DECIMAL(5,2)) AS `gmroi_impact_percentage`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    CASE lower(trim(`priority_level`))
      WHEN 'critical' THEN 'critical'
      WHEN 'high' THEN 'high'
      WHEN 'medium' THEN 'medium'
      WHEN 'low' THEN 'low'
      ELSE NULLIF(trim(`priority_level`), '')
    END AS `priority_level`,
    NULLIF(trim(`resolution_notes`), '') AS `resolution_notes`,
    COALESCE(try_to_date(trim(`retailer_claim_date`), 'yyyy-MM-dd'), try_to_date(trim(`retailer_claim_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`retailer_claim_date`) AS DATE)) AS `retailer_claim_date`,
    NULLIF(trim(`retailer_contact_email`), '') AS `retailer_contact_email`,
    NULLIF(trim(`retailer_contact_name`), '') AS `retailer_contact_name`,
    TRY_CAST(NULLIF(trim(`roi_impact_amount`), '') AS DECIMAL(18,2)) AS `roi_impact_amount`,
    TRY_CAST(NULLIF(trim(`settled_amount`), '') AS DECIMAL(18,2)) AS `settled_amount`,
    COALESCE(try_to_date(trim(`settlement_date`), 'yyyy-MM-dd'), try_to_date(trim(`settlement_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`settlement_date`) AS DATE)) AS `settlement_date`,
    CASE lower(trim(`settlement_method`))
      WHEN 'credit_memo' THEN 'credit_memo'
      WHEN 'check' THEN 'check'
      WHEN 'offset_future_invoice' THEN 'offset_future_invoice'
      WHEN 'write_off' THEN 'write_off'
      WHEN 'bank_transfer' THEN 'bank_transfer'
      ELSE NULLIF(trim(`settlement_method`), '')
    END AS `settlement_method`,
    NULLIF(trim(`settlement_reason_code`), '') AS `settlement_reason_code`,
    COALESCE(try_to_date(trim(`sla_resolution_date`), 'yyyy-MM-dd'), try_to_date(trim(`sla_resolution_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`sla_resolution_date`) AS DATE)) AS `sla_resolution_date`,
    CASE lower(trim(`source`))
      WHEN 'retailer_portal' THEN 'retailer_portal'
      WHEN 'edi_846' THEN 'edi_846'
      WHEN 'manual_entry' THEN 'manual_entry'
      WHEN 'bank_reconciliation' THEN 'bank_reconciliation'
      WHEN 'automated_matching' THEN 'automated_matching'
      ELSE NULLIF(trim(`source`), '')
    END AS `source`,
    NULLIF(trim(`supporting_document_url`), '') AS `supporting_document_url`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.promotion_deduction
)
SELECT *
FROM typed
QUALIFY `deduction_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `deduction_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- promotion.deduction_settlement ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.promotion_deduction_settlement (
  CONSTRAINT `deduction_settlement_id_not_null` EXPECT (`deduction_settlement_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: promotion.deduction_settlement typed and cleaned, one row per deduction_settlement_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`deduction_settlement_id`), '') AS BIGINT) AS `deduction_settlement_id`,
    TRY_CAST(NULLIF(trim(`accrual_id`), '') AS BIGINT) AS `accrual_id`,
    TRY_CAST(NULLIF(trim(`deduction_id`), '') AS BIGINT) AS `deduction_id`,
    TRY_CAST(NULLIF(trim(`funding_agreement_id`), '') AS BIGINT) AS `funding_agreement_id`,
    TRY_CAST(NULLIF(trim(`parent_settlement_deduction_settlement_id`), '') AS BIGINT) AS `parent_settlement_deduction_settlement_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    COALESCE(try_to_date(trim(`approval_date`), 'yyyy-MM-dd'), try_to_date(trim(`approval_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approval_date`) AS DATE)) AS `approval_date`,
    TRY_CAST(NULLIF(trim(`approved_amount`), '') AS DECIMAL(18,2)) AS `approved_amount`,
    NULLIF(trim(`business_unit_code`), '') AS `business_unit_code`,
    NULLIF(trim(`cost_center_code`), '') AS `cost_center_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`deduction_claimed_amount`), '') AS DECIMAL(18,2)) AS `deduction_claimed_amount`,
    CASE lower(trim(`dispute_resolution_method`))
      WHEN 'negotiation' THEN 'negotiation'
      WHEN 'arbitration' THEN 'arbitration'
      WHEN 'escalation' THEN 'escalation'
      WHEN 'partial_approval' THEN 'partial_approval'
      WHEN 'full_approval' THEN 'full_approval'
      WHEN 'write_off' THEN 'write_off'
      ELSE NULLIF(trim(`dispute_resolution_method`), '')
    END AS `dispute_resolution_method`,
    TRY_CAST(NULLIF(trim(`disputed_amount`), '') AS DECIMAL(18,2)) AS `disputed_amount`,
    TRY_CAST(NULLIF(trim(`fiscal_period`), '') AS INT) AS `fiscal_period`,
    TRY_CAST(NULLIF(trim(`fiscal_year`), '') AS INT) AS `fiscal_year`,
    NULLIF(trim(`gl_account_code`), '') AS `gl_account_code`,
    CASE WHEN lower(trim(`is_partial_settlement`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_partial_settlement`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_partial_settlement`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    COALESCE(try_to_date(trim(`payment_date`), 'yyyy-MM-dd'), try_to_date(trim(`payment_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`payment_date`) AS DATE)) AS `payment_date`,
    NULLIF(trim(`payment_reference_number`), '') AS `payment_reference_number`,
    NULLIF(trim(`profit_center_code`), '') AS `profit_center_code`,
    TRY_CAST(NULLIF(trim(`settled_amount`), '') AS DECIMAL(18,2)) AS `settled_amount`,
    TRY_CAST(NULLIF(trim(`settlement_cycle_time_days`), '') AS INT) AS `settlement_cycle_time_days`,
    COALESCE(try_to_date(trim(`settlement_date`), 'yyyy-MM-dd'), try_to_date(trim(`settlement_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`settlement_date`) AS DATE)) AS `settlement_date`,
    CASE lower(trim(`settlement_method`))
      WHEN 'credit_memo' THEN 'credit_memo'
      WHEN 'check' THEN 'check'
      WHEN 'wire_transfer' THEN 'wire_transfer'
      WHEN 'offset_invoice' THEN 'offset_invoice'
      WHEN 'write_off' THEN 'write_off'
      WHEN 'accrual_adjustment' THEN 'accrual_adjustment'
      ELSE NULLIF(trim(`settlement_method`), '')
    END AS `settlement_method`,
    NULLIF(trim(`settlement_notes`), '') AS `settlement_notes`,
    NULLIF(trim(`settlement_number`), '') AS `settlement_number`,
    NULLIF(trim(`settlement_reason_code`), '') AS `settlement_reason_code`,
    NULLIF(trim(`settlement_reason_description`), '') AS `settlement_reason_description`,
    NULLIF(trim(`settlement_status`), '') AS `settlement_status`,
    CASE WHEN lower(trim(`sla_compliance_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`sla_compliance_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `sla_compliance_flag`,
    NULLIF(trim(`source_system_code`), '') AS `source_system_code`,
    NULLIF(trim(`source_system_record_code`), '') AS `source_system_record_code`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.promotion_deduction_settlement
)
SELECT *
FROM typed
QUALIFY `deduction_settlement_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `deduction_settlement_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- promotion.promoted_price ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.promotion_promoted_price (
  CONSTRAINT `promoted_price_id_not_null` EXPECT (`promoted_price_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: promotion.promoted_price typed and cleaned, one row per promoted_price_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`promoted_price_id`), '') AS BIGINT) AS `promoted_price_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`funding_agreement_id`), '') AS BIGINT) AS `funding_agreement_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    TRY_CAST(NULLIF(trim(`trade_promotion_id`), '') AS BIGINT) AS `trade_promotion_id`,
    CASE lower(trim(`accrual_method`))
      WHEN 'scan_back' THEN 'scan_back'
      WHEN 'bill_back' THEN 'bill_back'
      WHEN 'off_invoice' THEN 'off_invoice'
      WHEN 'lump_sum' THEN 'lump_sum'
      WHEN 'performance_based' THEN 'performance_based'
      ELSE NULLIF(trim(`accrual_method`), '')
    END AS `accrual_method`,
    COALESCE(try_to_date(trim(`approval_date`), 'yyyy-MM-dd'), try_to_date(trim(`approval_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`approval_date`) AS DATE)) AS `approval_date`,
    NULLIF(trim(`approval_status`), '') AS `approval_status`,
    TRY_CAST(NULLIF(trim(`cost_of_goods_sold`), '') AS DECIMAL(18,4)) AS `cost_of_goods_sold`,
    NULLIF(trim(`country_code`), '') AS `country_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    TRY_CAST(NULLIF(trim(`estimated_volume_lift`), '') AS DECIMAL(10,2)) AS `estimated_volume_lift`,
    CASE lower(trim(`funding_source`))
      WHEN 'manufacturer' THEN 'manufacturer'
      WHEN 'retailer' THEN 'retailer'
      WHEN 'co_op' THEN 'co_op'
      WHEN 'vendor' THEN 'vendor'
      WHEN 'third_party' THEN 'third_party'
      ELSE NULLIF(trim(`funding_source`), '')
    END AS `funding_source`,
    CASE WHEN lower(trim(`is_advertised`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_advertised`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_advertised`,
    CASE WHEN lower(trim(`is_stackable`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_stackable`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_stackable`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`maximum_purchase_quantity`), '') AS INT) AS `maximum_purchase_quantity`,
    TRY_CAST(NULLIF(trim(`minimum_purchase_quantity`), '') AS INT) AS `minimum_purchase_quantity`,
    TRY_CAST(NULLIF(trim(`price_reduction_percentage`), '') AS DECIMAL(5,2)) AS `price_reduction_percentage`,
    NULLIF(trim(`pricing_strategy_type`), '') AS `pricing_strategy_type`,
    TRY_CAST(NULLIF(trim(`promotional_allowance_amount`), '') AS DECIMAL(18,4)) AS `promotional_allowance_amount`,
    TRY_CAST(NULLIF(trim(`promotional_price_amount`), '') AS DECIMAL(18,4)) AS `promotional_price_amount`,
    NULLIF(trim(`promotional_price_code`), '') AS `promotional_price_code`,
    NULLIF(trim(`promotional_price_description`), '') AS `promotional_price_description`,
    NULLIF(trim(`promotional_price_name`), '') AS `promotional_price_name`,
    NULLIF(trim(`region_code`), '') AS `region_code`,
    TRY_CAST(NULLIF(trim(`regular_shelf_price`), '') AS DECIMAL(18,4)) AS `regular_shelf_price`,
    TRY_CAST(NULLIF(trim(`retailer_margin_percentage`), '') AS DECIMAL(5,2)) AS `retailer_margin_percentage`,
    TRY_CAST(NULLIF(trim(`scan_back_rate`), '') AS DECIMAL(18,4)) AS `scan_back_rate`,
    NULLIF(trim(`tpm_system_code`), '') AS `tpm_system_code`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.promotion_promoted_price
)
SELECT *
FROM typed
QUALIFY `promoted_price_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `promoted_price_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;
